create table xxventuri.tmp_sales_cust_rep_up (
    id      number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20 noorder
    nocycle nokeep noscale not null enable,
    sl_no   number,
    account varchar2(255 byte),
    name    varchar2(100 byte)
);

alter table xxventuri.tmp_sales_cust_rep_up add primary key ( id )
    using index enable;


